<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { ask, err, isDemo, type AskResult, type Citation } from "./api";
import { useRoute } from "vue-router";
import { askView } from "./ask-result";
import { queryPlanFrom, type QueryPlan } from "./query-plan";
import { parseSse } from "./sse";
import { assistantScope, type AssistantScope } from "./assistant-scope";
const categoryName: Record<string, string> = { model_release: "模型发布", agent_tool: "智能体工具", framework_sdk: "框架与 SDK", research: "研究", product: "产品", industry: "产业" };
const open=ref(false),question=ref(""),running=ref(false),result=ref<AskResult>(),error=ref<ReturnType<typeof err>>(),status=ref(""),tokens=ref(""),sources=ref<Citation[]>([]),metrics=ref<Pick<AskResult,"scope_total"|"retrieved_count"|"summarized_count"|"citation_count"|"coverage">&{status?:string}>(),expanded=ref<number>(),plan=ref<QueryPlan>(),rulePlan=ref<QueryPlan>(),ruleError=ref(""),planning=ref(false),askedScope=ref(""),askedMode=ref<"demo"|"live">("live"),returnFocus=ref<HTMLElement>();
const clone=(x:AssistantScope):AssistantScope=>({label:x.label,snapshot:x.snapshot,filters:{...x.filters}});
const pendingScope=ref(clone(assistantScope)),activeScope=ref(clone(assistantScope));
let controller:AbortController|undefined,ruleController:AbortController|undefined,answerGeneration=0,ruleGeneration=0,timers:number[]=[];
const activeMode = ref<"demo" | "live">(isDemo() ? "demo" : "live");
const scopeIssue=computed(() => { const filters=activeScope.value.filters; if (filters.date_from && filters.date_to && filters.date_from > filters.date_to) return "当前范围的起始日期晚于截止日期。"; if (filters.date_from && filters.date_to) { const span=(Date.parse(filters.date_to + "T00:00:00Z")-Date.parse(filters.date_from + "T00:00:00Z"))/86400000+1; if (span>366) return "当前范围超过 366 天，请缩小范围后提问。"; } return ""; });
const scopeChanged=computed(()=>pendingScope.value.snapshot!==activeScope.value.snapshot || JSON.stringify(pendingScope.value.filters)!==JSON.stringify(activeScope.value.filters) || (isDemo() ? "demo" : "live")!==activeMode.value);
const errorGuidance:Record<string,string>={MODEL_UNAVAILABLE:"生成模型尚未配置，已显示可用的检索范围。",QUERY_UNSUPPORTED:"当前问题包含暂不支持的检索表达。",CLARIFICATION_REQUIRED:"需要先澄清检索条件后才能继续。"};
const errorDescription=(value:ReturnType<typeof err>)=>errorGuidance[value.code]?`${errorGuidance[value.code]} ${value.message}`:value.message;
const validUrl=(url:string)=>/^https?:\/\//i.test(url);
function openPanel(event:Event){returnFocus.value=event.currentTarget as HTMLElement;open.value=true;void nextTick(()=>document.querySelector<HTMLElement>(".assistant-close")?.focus());}
function closePanel(){if(running.value)cancel();open.value=false;void nextTick(()=>returnFocus.value?.focus());}
function applyCurrentScope(){activeScope.value=clone(pendingScope.value);activeMode.value=isDemo()?"demo":"live";status.value="已采用当前页面范围；下一次提问会使用它。";}
function hasNarrowEntityRole(value: QueryPlan) { const roles = value.entity_roles || []; return roles.length > 0 && !(roles.includes("subject") && roles.includes("product")); }
function applyRulePlan() { const value = rulePlan.value; if (!value) return; if (scopeChanged.value) { ruleError.value = "请先采用当前页面范围，再应用规则到当前总览。"; return; } if (value.requires_clarification || value.free_text || value.filters.entity_ids?.length || hasNarrowEntityRole(value)) { ruleError.value = "该解析包含无法由当前页面筛选完整表达的条件。"; return; } window.dispatchEvent(new CustomEvent("assistant-apply-plan", { detail: value.filters })); status.value = "规则范围已应用到当前总览；请在范围稳定后采用并提问。"; rulePlan.value = undefined; }
function slowStream(){let control:ReadableStreamDefaultController<Uint8Array>;const emit=(value:string,ms:number)=>timers.push(window.setTimeout(()=>control.enqueue(new TextEncoder().encode(value)),ms));return new ReadableStream({start(c){control=c;emit('event: status\ndata: {"phase":"retrieving"}\n\n',150);emit('event: token\ndata: {"text":"这是"}\n\n',450);emit('event: token\ndata: {"text":"明确标注的模拟回答。[2]"}\n\n',850);emit('event: sources\ndata: {"items":[{"index":2,"title":"合成演示来源","source_url":"https://example.invalid/demo","quote_text":"合成段落摘录","paragraph_id":"demo-p-001"}]}\n\n',1150);emit('event: done\ndata: {"status":"completed","scope_total":1,"retrieved_count":1,"summarized_count":1,"citation_count":1,"coverage":"complete"}\n\n',1450);timers.push(window.setTimeout(()=>c.close(),1600));},cancel(){timers.forEach(clearTimeout);timers=[];}});}
async function submit(){if(!question.value.trim()||running.value||scopeIssue.value)return;const current=++answerGeneration;controller?.abort();timers.forEach(clearTimeout);timers=[];controller=new AbortController();result.value=undefined;plan.value=undefined;error.value=undefined;tokens.value="";sources.value=[];metrics.value=undefined;running.value=true;askedScope.value=activeScope.value.snapshot;askedMode.value=activeMode.value;try{if(askedMode.value==="demo"){for await(const event of parseSse(slowStream(),controller.signal)){if(current!==answerGeneration)return;if(event.event==="status")status.value="模拟流：正在检索";if(event.event==="token")tokens.value+=JSON.parse(event.data).text;if(event.event==="sources")sources.value=JSON.parse(event.data).items as Citation[];if(event.event==="done"){const done=JSON.parse(event.data) as Pick<AskResult,"scope_total"|"retrieved_count"|"summarized_count"|"citation_count"|"coverage">&{status?:string};metrics.value=done;status.value=done.status==="completed"?"模拟流已完成":"模拟流失败";}}}else{status.value="正在检索并汇总…";const response=await ask({question:question.value.trim(),filters:activeScope.value.filters,timezone:"Asia/Shanghai",answer_mode:"concise",client_request_id:crypto.randomUUID()},controller.signal);if(current!==answerGeneration)return;plan.value=queryPlanFrom(response);const view=askView(response);result.value=response;sources.value=view.citations;metrics.value=response;status.value=view.status;}}catch(cause){if(current!==answerGeneration)return;if((cause as Error).name==="AbortError")status.value="已取消，未自动重试。";else{error.value=err(cause);plan.value=queryPlanFrom(cause);}}finally{if(current===answerGeneration)running.value=false;}}
function cancel(){answerGeneration++;controller?.abort();timers.forEach(clearTimeout);timers=[];running.value=false;status.value="已取消，未自动重试。";}
async function planFromQuestion(){if(!question.value.trim())return;const current=++ruleGeneration;ruleController?.abort();ruleController=new AbortController();ruleError.value="";rulePlan.value=undefined;planning.value=true;try{const response=await fetch("/api/v1/query-plan",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({question:question.value.trim(),filters:activeScope.value.filters,timezone:"Asia/Shanghai",client_request_id:crypto.randomUUID()}),signal:ruleController.signal});if(!response.ok)throw new Error("规则解析请求失败");const parsed=queryPlanFrom({query_plan_public:await response.json()});if(!parsed)throw new Error("规则解析结果无效");if(current!==ruleGeneration)return;rulePlan.value=parsed;}catch(cause){if(current===ruleGeneration&&(cause as Error).name!=="AbortError")ruleError.value=cause instanceof Error?cause.message:"规则解析失败";}finally{if(current===ruleGeneration)planning.value=false;}}
async function toggle(index:number){expanded.value=expanded.value===index?undefined:index;await nextTick();document.getElementById(`assistant-citation-${index}`)?.focus();}
function onKeydown(event:KeyboardEvent){if(event.key==="Escape"&&open.value){event.preventDefault();closePanel();return;} if(event.key !== "Tab" || !matchMedia("(max-width: 900px)").matches) return; const nodes = [...document.querySelectorAll<HTMLElement>("#global-assistant button, #global-assistant textarea, #global-assistant a")].filter((node) => !node.hasAttribute("disabled")); const first = nodes[0], last = nodes[nodes.length - 1]; if (!first || !last) return; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }}
const onDocumentKeydown = (event: KeyboardEvent) => { if (event.key === "Escape" && open.value) { event.preventDefault(); closePanel(); } };
watch(assistantScope,(scope)=>{pendingScope.value=clone(scope);if(!askedScope.value&&!running.value) { activeScope.value=clone(scope); activeMode.value=isDemo()?"demo":"live"; }},{deep:true,immediate:true});
watch(question,()=>{ruleGeneration++;ruleController?.abort();rulePlan.value=undefined;ruleError.value="";});
watch(open, (value) => { document.documentElement.classList.toggle("global-assistant-open", value); const mobile = matchMedia("(max-width: 900px)").matches; document.querySelector(".app-content main")?.toggleAttribute("inert", value && mobile); document.querySelector(".app-rail")?.toggleAttribute("inert", value && mobile); });
onMounted(() => document.addEventListener("keydown", onDocumentKeydown));
onBeforeUnmount(()=>{ document.removeEventListener("keydown", onDocumentKeydown); document.documentElement.classList.remove("global-assistant-open"); answerGeneration++;ruleGeneration++;controller?.abort();ruleController?.abort();timers.forEach(clearTimeout);});
</script>
<template>
<button class="assistant-trigger" data-testid="assistant-toggle" :aria-expanded="open" aria-controls="global-assistant" @click="openPanel">提问</button>
<aside v-show="open" id="global-assistant" class="assistant-panel" data-testid="global-assistant" :inert="!open" aria-label="全站研究助手" @keydown="onKeydown">
<header class="assistant-panel__header"><div><strong>研究助手</strong><p class="meta">基于已收录事件回答，不使用维护权限。</p></div><button class="assistant-close" aria-label="关闭研究助手" @click="closePanel">返回</button></header>
<section class="assistant-scope" aria-label="当前检索范围"><p><strong>{{ activeScope.label }}</strong></p><p class="meta">{{ activeScope.snapshot }}</p><button v-if="scopeChanged" @click="applyCurrentScope">采用此页面的新范围</button><p v-if="scopeChanged" class="meta">页面范围已变化；已有回答仍保留原范围快照。</p></section>
<section class="assistant-question ask-question"><label>问题<textarea v-model="question" class="control" rows="4" placeholder="输入需要核查的 AI 进展问题" /></label><div class="row assistant-actions"><button class="primary" :disabled="running||!question.trim()||Boolean(scopeIssue)" @click="submit">开始分析</button><button :disabled="planning||!question.trim()" @click="planFromQuestion">按问题筛选</button><button v-if="running" @click="cancel">取消</button></div>
</section><p v-if="scopeIssue" class="error" role="alert">{{ scopeIssue }}</p><p v-if="ruleError" class="error" role="alert">{{ ruleError }}</p><section v-if="rulePlan" class="query-plan assistant-plan"><h2>规则解析预览</h2><p>解析分类：{{ rulePlan.filters.category ? (categoryName[rulePlan.filters.category] || rulePlan.filters.category) : "未限定" }} · 日期：{{ rulePlan.filters.date_from||"未限定" }} 至 {{ rulePlan.filters.date_to||"未限定" }}。</p><p>拟应用：分类 {{ rulePlan.filters.category ? (categoryName[rulePlan.filters.category] || rulePlan.filters.category) : "沿用当前" }} · 日期 {{ rulePlan.filters.date_from || "沿用当前" }} 至 {{ rulePlan.filters.date_to || "沿用当前" }}（起止日期均包含）。</p><p v-if="rulePlan.filters.entity_ids?.length" class="meta">实体：{{ rulePlan.filters.entity_match === "all" ? "同时匹配" : "任一匹配" }} {{ rulePlan.filters.entity_ids.length }} 个实体。</p><p v-if="rulePlan.entity_roles?.length" class="meta">实体角色：{{ rulePlan.entity_roles.map((role) => role === "subject" ? "主体" : "产品").join("、") }}</p><p v-if="rulePlan.requires_clarification||rulePlan.free_text" class="meta">部分条件需要澄清，提问时仍沿用已采用的页面范围。</p><button @click="applyRulePlan">应用到总览</button><ul v-if="rulePlan.warnings.length"><li v-for="warning in rulePlan.warnings" :key="warning">{{ warning }}</li></ul></section>
<p class="meta" aria-live="polite">{{ status }}</p><p v-if="error" class="meta">本次范围：{{ askedScope }} · {{ askedMode === "demo" ? "模拟数据" : "服务数据" }}</p><div v-if="error" class="assistant-error error" role="alert"><strong>{{ error.code }}</strong>：{{ errorDescription(error) }}</div><section v-if="plan" class="query-plan assistant-plan" aria-label="检索范围" data-testid="query-plan"><h2>检索范围</h2><p>业务日期：{{ plan.business_date }} · 时区：{{ plan.timezone }}</p><p>分类：{{ plan.filters.category ? (categoryName[plan.filters.category] || plan.filters.category) : "全部分类" }} · 日期：{{ plan.filters.date_from||"不限" }} 至 {{ plan.filters.date_to||"不限" }}（起止日期均包含）。</p><p>实体：{{ plan.filters.entity_ids?.length ? `${plan.filters.entity_match === "all" ? "同时匹配" : "任一匹配"} ${plan.filters.entity_ids.length} 个实体` : "未限定实体" }}</p><p v-if="plan.entity_roles?.length">实体角色：{{ plan.entity_roles.map((role) => role === "subject" ? "主体" : "产品").join("、") }}</p><p v-if="plan.requires_clarification">需要澄清：<span v-for="item in plan.clarification_candidates" :key="item.label">{{ item.label }} </span></p><p v-if="plan.free_text">未理解限制：{{ plan.free_text }}</p><ul v-if="plan.warnings.length"><li v-for="warning in plan.warnings" :key="warning">{{ warning }}</li></ul></section>
<article v-if="result||tokens" class="assistant-answer" data-testid="ask-answer"><p class="meta">回答绑定范围：{{ askedScope }}</p><p v-if="askedMode==='demo'" class="demo">模拟流，仅用于演示。</p><h2>回答</h2><p class="answer-body">{{ tokens||result?.answer }}</p><div v-for="source in sources" :key="source.index" class="evidence-item"><button :aria-expanded="expanded===source.index" :aria-controls="`assistant-citation-${source.index}`" @click="toggle(source.index)">[{{ source.index }}] {{ source.title }}</button><blockquote v-if="expanded===source.index" :id="`assistant-citation-${source.index}`" tabindex="-1">{{ source.quote_text||"无段落摘录" }}<footer class="meta">段落 {{ source.paragraph_id||"未提供" }}</footer></blockquote><a v-if="validUrl(source.source_url)" :href="source.source_url" target="_blank" rel="noopener">打开来源</a></div><p v-if="result?.answer_status==='no_answer'">没有可回答的资料。</p><p v-if="metrics?.coverage==='partial'" class="meta">覆盖不完整：答案仅基于部分匹配资料。</p><p v-if="metrics" class="meta tabular">完整匹配 {{ metrics.scope_total }} · 取回 {{ metrics.retrieved_count }} · 总结 {{ metrics.summarized_count }} · 引用 {{ metrics.citation_count }} · 覆盖：{{ metrics.coverage }}</p></article>
</aside>
</template>